const TIME_TO_GO_MAX_S = 864000; // Victron caps TimeToGo at 10 days

if (msg.topic === "LiFePo01/battery") {
    const p = msg.payload;
    const payload = {
        "Dc/0/Voltage": p.total_voltage_v,
        "Dc/0/Current": p.current_a,
        "Dc/0/Power": p.power_w,
        "Soc": p.soc_percent,
        "Soh": p.soh_percent,
        "Dc/0/Temperature": p.cell_temperature_c,
        "Capacity": p.full_charge_capacity_ah
    };

    // Estimated remaining runtime: only meaningful while discharging
    // (time until the pack is empty at the current draw).
    if (p.current_a < 0 && p.remaining_capacity_ah != null) {
        const hours = p.remaining_capacity_ah / Math.abs(p.current_a);
        payload["TimeToGo"] = Math.min(Math.round(hours * 3600), TIME_TO_GO_MAX_S);
    } else {
        payload["TimeToGo"] = TIME_TO_GO_MAX_S; // charging/idle: no drain, report max
    }

    msg.payload = payload;
    return msg;
}

if (msg.topic === "LiFePo01/battery/cells") {
    const cells = msg.payload;
    if (Array.isArray(cells) && cells.length > 0) {
        msg.payload = {
            "System/MinCellVoltage": Math.min(...cells),
            "System/MaxCellVoltage": Math.max(...cells)
        };
        return msg;
    }
}

return null;
